using Clary.Api.Identity;
namespace Clary.Api;
public static class TicketEndpoints {
 public static void MapTicketEndpoints(this WebApplication app){
  var group=app.MapGroup("/api/tickets").WithMetadata(new CompanyPermission(CompanyCapability.OwnInventory));
  group.MapGet("",(HttpContext h,TicketRepository r,string? search,string? status,string? type,string? priority,Guid? assigneeId,Guid? recipientId,Guid? assetId,Guid? locationId,bool? overdue,DateOnly? today,int? limit,string? cursor)=>EquipmentEndpoints.Handle(async()=>await r.ListAsync(CompanyPolicies.Context(h)!,new(search,status,type,assigneeId,recipientId,assetId,locationId,overdue??false,today,limit??50,cursor,priority),h.RequestAborted)));
  group.MapGet("/{id:guid}/attachments",(HttpContext h,TicketRepository r,Guid id)=>EquipmentEndpoints.Handle(async()=>await r.AttachmentsAsync(CompanyPolicies.Context(h)!,id,h.RequestAborted)));
  group.MapPost("/{id:guid}/attachments",(HttpContext h,TicketRepository r,Guid id)=>EquipmentEndpoints.Handle(async()=>{if(!h.Request.HasFormContentType)throw new ArgumentException("Choose a file.");var form=await h.Request.ReadFormAsync(h.RequestAborted);var file=form.Files.GetFile("file");if(file is null||file.Length<1||file.Length>10485760)throw new ArgumentException("Choose a file up to 10 MB.");using var buffer=new MemoryStream();await file.CopyToAsync(buffer,h.RequestAborted);return await r.AddAttachmentAsync(CompanyPolicies.Context(h)!,id,file.FileName,buffer.ToArray(),h.RequestAborted);})).DisableAntiforgery();
  group.MapDelete("/{id:guid}/attachments/{attachment:guid}",(HttpContext h,TicketRepository r,Guid id,Guid attachment)=>EquipmentEndpoints.Handle(async()=>await r.RemoveAttachmentAsync(CompanyPolicies.Context(h)!,id,attachment,h.RequestAborted)));
  group.MapGet("/{id:guid}/attachments/{attachment:guid}",async(HttpContext h,TicketRepository r,Guid id,Guid attachment)=>{try{var file=await r.OpenAttachmentAsync(CompanyPolicies.Context(h)!,id,attachment,h.RequestAborted);return Results.File(file.Content,"application/octet-stream",file.Filename);}catch(InventoryMissing){return Results.NotFound();}catch(CompanyDenied){return Results.StatusCode(403);}});
  group.MapGet("/reports",(HttpContext h,TicketRepository r,string subject,string? status,string? type,Guid? recipientId,Guid? locationId,Guid? assetId,Guid? assigneeId,bool? overdue,DateOnly? today,int? limit,string? cursor)=>EquipmentEndpoints.Handle(async()=>await r.ReportAsync(CompanyPolicies.Context(h)!,subject,new(Status:status,Type:type,AssigneeId:assigneeId,RecipientId:recipientId,AssetId:assetId,LocationId:locationId,Overdue:overdue??false,Today:today,Limit:limit??50,Cursor:cursor),h.RequestAborted)));
  group.MapGet("/templates",(HttpContext h,TicketRepository r)=>EquipmentEndpoints.Handle(async()=>await r.TemplatesAsync(CompanyPolicies.Context(h)!,h.RequestAborted)));
  group.MapPost("/templates",(HttpContext h,TicketRepository r,TicketTemplateInput input)=>EquipmentEndpoints.Handle(async()=>await r.SaveTemplateAsync(CompanyPolicies.Context(h)!,null,input,h.RequestAborted)));
  group.MapPut("/templates/{id:guid}",(HttpContext h,TicketRepository r,Guid id,TicketTemplateInput input)=>EquipmentEndpoints.Handle(async()=>await r.SaveTemplateAsync(CompanyPolicies.Context(h)!,id,input,h.RequestAborted)));
  group.MapPut("/{id:guid}/checklist/{item:guid}",(HttpContext h,TicketRepository r,Guid id,Guid item,TicketChecklistInput input)=>EquipmentEndpoints.Handle(async()=>await r.CheckAsync(CompanyPolicies.Context(h)!,id,item,input,h.RequestAborted)));
  group.MapGet("/assignees",(HttpContext h,TicketRepository r)=>EquipmentEndpoints.Handle(async()=>await r.AssigneesAsync(CompanyPolicies.Context(h)!,h.RequestAborted)));
  group.MapGet("/settings",(HttpContext h,TicketRepository r)=>EquipmentEndpoints.Handle(async()=>await r.SettingsAsync(CompanyPolicies.Context(h)!,null,h.RequestAborted)));
  group.MapPut("/settings",(HttpContext h,TicketRepository r,TicketSettings input)=>EquipmentEndpoints.Handle(async()=>await r.SettingsAsync(CompanyPolicies.Context(h)!,input,h.RequestAborted)));
  group.MapPost("",(HttpContext h,TicketRepository r,TicketInput input)=>EquipmentEndpoints.Handle(async()=>await r.SaveAsync(CompanyPolicies.Context(h)!,null,input,h.RequestAborted)));
  group.MapGet("/{id:guid}",(HttpContext h,TicketRepository r,Guid id)=>EquipmentEndpoints.Handle(async()=>await r.GetAsync(CompanyPolicies.Context(h)!,id,h.RequestAborted)));
  group.MapPut("/{id:guid}",(HttpContext h,TicketRepository r,Guid id,TicketInput input)=>EquipmentEndpoints.Handle(async()=>await r.SaveAsync(CompanyPolicies.Context(h)!,id,input,h.RequestAborted)));
  group.MapPost("/{id:guid}/actions",(HttpContext h,TicketRepository r,Guid id,TicketActionInput input)=>EquipmentEndpoints.Handle(async()=>await r.ActionAsync(CompanyPolicies.Context(h)!,id,input,h.RequestAborted)));
  group.MapPost("/{id:guid}/prepare",(HttpContext h,TicketRepository r,Guid id)=>EquipmentEndpoints.Handle(async()=>await r.PrepareAsync(CompanyPolicies.Context(h)!,id,h.RequestAborted)));
  group.MapGet("/{id:guid}/comments",(HttpContext h,TicketRepository r,Guid id,int? limit,string? cursor)=>EquipmentEndpoints.Handle(async()=>await r.FeedAsync(CompanyPolicies.Context(h)!,id,true,limit??30,cursor,h.RequestAborted)));
  group.MapPost("/{id:guid}/comments",(HttpContext h,TicketRepository r,Guid id,TicketCommentInput input)=>EquipmentEndpoints.Handle(async()=>await r.AddCommentAsync(CompanyPolicies.Context(h)!,id,input,h.RequestAborted)));
  group.MapGet("/{id:guid}/activity",(HttpContext h,TicketRepository r,Guid id,int? limit,string? cursor)=>EquipmentEndpoints.Handle(async()=>await r.FeedAsync(CompanyPolicies.Context(h)!,id,false,limit??30,cursor,h.RequestAborted)));
 }
}
